class TaskManager:
    """Manages a collection of tasks with filtering and statistics."""

    def __init__(self):
        self.tasks = {}

    def add_task(self, title, description="", priority=2, due_date=None):
        task = Task(title, description, priority, due_date)
        self.tasks[task.id] = task
        return task

    def get_task(self, task_id):
        if task_id not in self.tasks:
            raise KeyError(f"No task with id {task_id}")
        return self.tasks[task_id]

    def delete_task(self, task_id):
        if task_id not in self.tasks:
            raise KeyError(f"No task with id {task_id}")
        del self.tasks[task_id]

    def find_by_tag(self, tag):
        return [t for t in self.tasks.values() if tag in t.tags]

    def find_overdue(self):
        return [t for t in self.tasks.values() if t.is_overdue()]

